(() => {
  // Wrapper de la Cloud Function crearPreferenciaPago (ver
  // functions/index.js) — arma la preferencia de Mercado Pago para la
  // seña de un turno ya guardado y devuelve la URL de checkout a la que
  // redirigir. El monto NUNCA lo calcula este archivo ni el cliente en
  // general: se recalcula del lado del servidor a partir de datos reales.
  window.crearPreferenciaPago = async ({ turnoId }) => {
    const llamarFuncion = firebase.functions().httpsCallable('crearPreferenciaPago');
    const resultado = await llamarFuncion({ turnoId, origin: window.location.origin });
    return resultado.data;
  };
})();
